window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"NFtbV2NJT3s","speaker":"Matthew Cooper Wale","role":"Prime Minister","country":"Solomon Islands","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=NFtbV2NJT3s","date":"20260925","title":"🇸🇧 Solomon Islands - Prime Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1654,"words":3359,"counts":{"claims":46,"promises":7,"attacks":0},"topics":[{"topic":"Solomon Islands governance","share":0.1551,"seconds":257},{"topic":"Pacific climate","share":0.1527,"seconds":253},{"topic":"UN reform","share":0.0856,"seconds":142},{"topic":"West Papua","share":0.0826,"seconds":137},{"topic":"Pacific security","share":0.0788,"seconds":130},{"topic":"Solomon Islands development","share":0.0748,"seconds":124},{"topic":"Solomon Islands ocean","share":0.0488,"seconds":81},{"topic":"Solomon Islands economy","share":0.0483,"seconds":80},{"topic":"UN diplomacy","share":0.0441,"seconds":73},{"topic":"Solomon Islands climate","share":0.041,"seconds":68},{"topic":"Global military","share":0.0388,"seconds":64},{"topic":"Solomon Islands justice","share":0.0388,"seconds":64},{"topic":"Solomon Islands digital","share":0.037,"seconds":61},{"topic":"Solomon Islands crime","share":0.0368,"seconds":61},{"topic":"Ocean pollution","share":0.0367,"seconds":61}],"timeline":[[4,68,"Solomon Islands governance"],[70,143,"UN diplomacy"],[145,207,"Solomon Islands development"],[209,274,"Solomon Islands governance"],[275,345,"Pacific security"],[347,408,"Solomon Islands crime"],[410,470,"Pacific security"],[472,533,"Solomon Islands digital"],[534,600,"Pacific climate"],[601,665,"Pacific climate"],[666,728,"Pacific climate"],[729,791,"Pacific climate"],[792,873,"Solomon Islands ocean"],[874,935,"Ocean pollution"],[937,998,"Solomon Islands development"],[1000,1068,"Solomon Islands climate"],[1070,1134,"Global military"],[1136,1216,"Solomon Islands economy"],[1217,1285,"UN reform"],[1287,1361,"UN reform"],[1362,1437,"West Papua"],[1438,1501,"West Papua"],[1502,1568,"Solomon Islands governance"],[1570,1631,"Solomon Islands governance"],[1632,1696,"Solomon Islands justice"],[1697,1712,null]],"stances":{"Solomon Islands governance":"Matthew Cooper Wale states he speaks on behalf of the Solomon Islands and its people, expressing their hopes for peace and dignity.","UN diplomacy":"Matthew Cooper Wale congratulates the new President, commends the predecessor and Secretary-General, and expresses hope for multilateralism despite current strains.","Solomon Islands development":"Matthew Cooper Wale states that his government is implementing a national transformation program focused on delivering tangible results in education, health, and infrastructure.","Pacific security":"Matthew Cooper Wale states that peace and security are inseparable from development, calls for the protection of civilians in armed conflicts, and highlights transnational criminal networks as a grave threat to the Pacific.","Solomon Islands crime":"Matthew Cooper Wale states that Solomon Islands is amending its dangerous drugs act to introduce stiffer penalties and strengthen law enforcement, while calling for international cooperation to combat transnational organized crime.","Solomon Islands digital":"Matthew Cooper Wale states that digital transformation aims to connect islands and open the economy, while advocating for inclusive AI governance and climate action.","Pacific climate":"Matthew Cooper Wale states that global climate action is insufficient, leading to severe consequences for Solomon Islands including loss of land and increased disasters, while noting the diversion of essential funds to recovery efforts.","Solomon Islands ocean":"Matthew Cooper Wale states that illegal fishing undermines the Solomon Islands' ability to benefit from its ocean and calls for increased funding for SDG14.","Ocean pollution":"Matthew Cooper Wale calls for an ambitious, legally binding treaty to address the full cycle of plastics from production to disposal.","Solomon Islands climate":"Matthew Cooper Wale states that the Solomon Islands faces fundamental vulnerability due to its status as a small island developing state and calls for international financial institutions to integrate the Multi-dimensional Vulnerability Index into their financing decisions.","Global military":"Matthew Cooper Wale argues that global military expenditure is disproportionately high compared to development aid and climate finance, creating an imbalance that must be corrected by redirecting funds.","Solomon Islands economy":"Matthew Cooper Wale states that the Solomon Islands government is implementing an agenda of public-private partnerships and infrastructure projects to prepare for graduation from least developed country status.","UN reform":"Matthew Cooper Wale argues that UN reforms must strengthen effectiveness and relevance without reducing services in vulnerable regions, while calling for the next Secretary-General to ensure equal accountability to all member states.","West Papua":"Matthew Cooper Wale calls for completing the unfinished work of decolonization and providing practical pathways for self-determination in non-self-governing territories.","Solomon Islands justice":"Matthew Cooper Wale argues that a nation's greatness is defined by its justice and treatment of the vulnerable rather than its military or alliances, and states his country's readiness to serve as a partner."},"claims":[{"t":54,"quote":"a nation of nearly a thousand islands stretching across as many miles of the blue Pacific","topic":"Solomon Islands governance","kind":"fact"},{"t":71,"quote":"I congratulate you on your election and assure you of the full support of Solomon Islands.","topic":"UN diplomacy","kind":"fact"},{"t":77,"quote":"I also commend your predecessor for her determined leadership of the 80th","topic":"UN diplomacy","kind":"fact"},{"t":85,"quote":"I pay special tribute to Secretary General Antonio Gutirez as he takes part in his final debate in office.","topic":"UN diplomacy","kind":"fact"},{"t":172,"quote":"We are providing universal free education so that no child is turned away from school because their family cannot afford the fees.","topic":"Solomon Islands development","kind":"fact"},{"t":181,"quote":"We are strengthening our health system with a renewed focus on tackling the scourge of non-communicable diseases, eradicating malaria, and building a new national referral hospital.","topic":"Solomon Islands development","kind":"fact"},{"t":209,"quote":"We are reforming our public finance systems so that every dollar delivers for our people and we are pursuing constitutional amendments to strengthen and stabilize our democracy.","topic":"Solomon Islands governance","kind":"fact"},{"t":332,"quote":"Transnational criminal networks are using our ocean as a highway for illicit drugs, undermining our sovereignty and national security, destroying young lives and tearing at the fabric of our communities.","topic":"Pacific security","kind":"fact"},{"t":375,"quote":"In August this year, Solomon Islands succeeded to the UN convention against transnational organized crime","topic":"Solomon Islands crime","kind":"fact"},{"t":416,"quote":"As enshrined in the Ocean of Peace Declaration, our region must remain free of nuclear weapons and free from destabilizing external influence.","topic":"Pacific security","kind":"fact"},{"t":430,"quote":"my government has proposed a treaty that would bind Pacific Island countries and like-minded partners to a firm shared commitment to keep the Pacific an ocean of peace.","topic":"Pacific security","kind":"fact"},{"t":484,"quote":"The completion of 161 telecommunication towers across the country will lift national broadband coverage from 56 to 86%.","topic":"Solomon Islands digital","kind":"number"},{"t":565,"quote":"This year, tropical cyclone miler, a category 5 storm, tore through our communities, destroying homes, schools, infrastructure, and livelihoods.","topic":"Pacific climate","kind":"fact"},{"t":577,"quote":"My government has just approved US 9.38 million for shelter recovery.","topic":"Pacific climate","kind":"number"},{"t":606,"quote":"My people did the least to cause this crisis, yet they pay its earliest and heaviest price","topic":"Pacific climate","kind":"fact"},{"t":617,"quote":"Last year, the International Court of Justice confirmed in its landmark advisory opinion that states have legal obligations to protect the climate","topic":"Pacific climate","kind":"fact"},{"t":689,"quote":"The pre-COP 31 meeting to be hosted in the Pacific by Australia in partnership with Fiji and Tuvalu will bring the reality of climate change directly into the heart of the global process.","topic":"Pacific climate","kind":"fact"},{"t":717,"quote":"Mr. President, Solomon Islands welcomes the convening of the second high level meeting on sea level rise and the adoption of the first political declaration on sea level rise.","topic":"Pacific climate","kind":"fact"},{"t":729,"quote":"Every day our people are defending their coastlines, strengthening their resilience, protecting their food and water security and their cultural heritage. and where there is no other choice, relocating.","topic":"Pacific climate","kind":"fact"},{"t":763,"quote":"Solomon Islands reaffirm reaffirms that maritime boundaries once established and deposited in accordance with UNCLO together with the rights and entitlements that flow from them shall continue to apply notwithstanding any physical changes caused by climate change related sea level rise.","topic":"Pacific climate","kind":"fact"},{"t":816,"quote":"illegal, unreported and unregulated fishing which costs our region US30 million every year","topic":"Solomon Islands ocean","kind":"number"},{"t":849,"quote":"With just four years left until 2030","topic":"Solomon Islands ocean","kind":"fact"},{"t":884,"quote":"Plastic pollution is poisoning our ocean and our food.","topic":"Ocean pollution","kind":"fact"},{"t":907,"quote":"With more than half of our population under the age of 25","topic":"Ocean pollution","kind":"number"},{"t":945,"quote":"our development partnerships play an indispensable role in expanding infrastructure, maritime connectivity, health and education, and in improving the lives of Solomon Islanders.","topic":"Solomon Islands development","kind":"fact"},{"t":977,"quote":"Partnerships among developing countries have enabled us to share expertise, technology, innovation and practical solutions suited to our circumstances.","topic":"Solomon Islands development","kind":"fact"},{"t":1038,"quote":"This a single natural disaster can erase years of investment and progress and push the nation backwards.","topic":"Solomon Islands climate","kind":"fact"},{"t":1047,"quote":"The multi-dimensional vulnerability index captures the special circumstances of of SIDS in a way that income measures alone does not.","topic":"Solomon Islands climate","kind":"fact"},{"t":1072,"quote":"last year the world's the world spent more than $3 trillion on its That is more than 16 times all ODA.","topic":"Global military","kind":"number"},{"t":1084,"quote":"In less than 18 days, the world spends more on arms than developed countries provide in a full year of climate finance.","topic":"Global military","kind":"fact"},{"t":1092,"quote":"In a in the same year that military spending reached its highest share of global output since 2009, development aid had its steepest fall on record.","topic":"Global military","kind":"fact"},{"t":1104,"quote":"Bilateral aid to the least developed countries fell by a quarter.","topic":"Global military","kind":"number"},{"t":1136,"quote":"Sir, Solman Islands is due to graduate from least developed country status in As part of our preparations","topic":"Solomon Islands economy","kind":"fact"},{"t":1159,"quote":"a second tuna canary at Beina Harour, upgraded airports, agricultural treatment facilities to support trade, and expanded road networks and maritime ports will shift the trajectory. of our At the same time","topic":"Solomon Islands economy","kind":"fact"},{"t":1218,"quote":"as the UN marks it its 81st anniversary","topic":"UN reform","kind":"fact"},{"t":1253,"quote":"The UN is not perfect, but it remains the cornerstone of multilateral diplomacy","topic":"UN reform","kind":"fact"},{"t":1313,"quote":"The veto is a relic of 1945. Too often, it has been used to shield violations of international law and to entrench the double standards that fuel conflict.","topic":"UN reform","kind":"fact"},{"t":1326,"quote":"At a minimum, the veto must never again be used in situations of genocide, crimes against humanity, or war crimes.","topic":"UN reform","kind":"fact"},{"t":1368,"quote":"Solman Islands looks forward to increasing its peacekeeping contribution in the coming year.","topic":"West Papua","kind":"fact"},{"t":1383,"quote":"Solomon Islands reaffirms its long-standing support for the right to self-determination of the Kanak people of New Calonia and the Maui Nui people of French Polynesia.","topic":"West Papua","kind":"fact"},{"t":1438,"quote":"Reports of human rights violations in West Papua have persisted for far too long.","topic":"West Papua","kind":"fact"},{"t":1528,"quote":"Our constitution was established under the guiding hand of God by a people conscious of our common destiny.","topic":"Solomon Islands governance","kind":"fact"},{"t":1570,"quote":"King Solomon, among the wisest rulers of antiquity, wrote, \"There are many devices in a man's heart. Nevertheless, the council of the Lord shall stand.\"","topic":"Solomon Islands governance","kind":"fact"},{"t":1598,"quote":"When Solomon was offered anything he he did not ask for riches or long life or the defeat of his enemies. He asked for an understanding heart so that he might judge his people well.","topic":"Solomon Islands governance","kind":"fact"},{"t":1644,"quote":"Righteousness exalts the nation. Not its arsenal, not its alliances, but its justice.","topic":"Solomon Islands justice","kind":"fact"},{"t":1678,"quote":"Our national moto teaches us that to lead is to serve.","topic":"Solomon Islands justice","kind":"fact"}],"promises":[{"t":361,"quote":"We are amending our dangerous drugs act to in introduce stiffer penalties as a deterrent and we are strengthening law enforcement to prevent and detect these crimes and to hold perpetrators accountable.","topic":"Solomon Islands crime","kind":"promise"},{"t":683,"quote":"Our region has long led on climate action and we will continue to lead.","topic":"Pacific climate","kind":"promise"},{"t":911,"quote":"my government is prioritizing legal frameworks that empower young people, advance gender equality, and strengthen the protection of women and children against domestic violence.","topic":"Ocean pollution","kind":"promise"},{"t":931,"quote":"Solomon Islands is committed to accelerating that progress at home.","topic":"Ocean pollution","kind":"promise"},{"t":1145,"quote":"my government is pursuing an ambitious and proactive agenda that uses public private partnerships to unlock investments in transformative projects","topic":"Solomon Islands economy","kind":"promise"},{"t":1175,"quote":"my government is strengthening our financial institutions and frameworks to improve revenue collection and accountability so that we can sustain our development priorities","topic":"Solomon Islands economy","kind":"promise"},{"t":1683,"quote":"In that spirit of service, Solomman Island stands ready to do its part as a willing partner and a committed member of this assembly.","topic":"Solomon Islands justice","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":4,"topic":"Solomon Islands governance","text":"The assembly will hear an address by His Excellency Matthew Cooper Whale, Prime Minister of Solomon Islands. I request protocol to escort his excellency and invite him to address the Mr. President, Secretary General of the United Nations, excellencies, distinguished delegates, I stand before this assembly conscious that I speak on behalf of a nation and the people whose future is being shaped in holes like this one. I bring warm greetings from the people and government of Solomon Islands, a nation of nearly a thousand islands stretching across as many miles of the blue Pacific. Our people hold the same hopes as people in every land to live in peace and to raise their children in dignity."},{"t":70,"topic":"UN diplomacy","text":"Mr. President, I congratulate you on your election and assure you of the full support of Solomon Islands. I also commend your predecessor for her determined leadership of the 80th I pay special tribute to Secretary General Antonio Gutirez as he takes part in his final debate in office. Mr. Secretary General, you have been a true champion of multilateralism and of small island developing states. Your unwavering advocacy on climate action and your repeated visits to our region told the world a simple truth that the Pacific matters and that our challenges and how the world responds to them remain a litmus test for this organization and for us all. We meet at a time when multilateralism is under serious strain and when the notion that might is right appears to be making a return. Yet we continue to gather in forums and dialogues around the world and here in the general assembly, the pinnacle of That in itself is course for hope."},{"t":145,"topic":"Solomon Islands development","text":"Mr. President, for my people, what is said in this hall is measured not in declarations but in results. Classrooms with teachers and books, clinics with medicines, roads that reach markets and villages that thrive. That is the lens through which Solomon Islands engages with the world. My government is delivering a program of national transformation. We are providing universal free education so that no child is turned away from school because their family cannot afford the fees. We are strengthening our health system with a renewed focus on tackling the scourge of non-communicable diseases, eradicating malaria, and building a new national referral hospital. We are prioritizing energy and other transformative infrastructure, expanding roads, ports, airports, and to connect our scattered islands into one national economy."},{"t":209,"topic":"Solomon Islands governance","text":"We are reforming our public finance systems so that every dollar delivers for our people and we are pursuing constitutional amendments to strengthen and stabilize our democracy. This is the agenda by which our people will judge my government. Mr. President, over the past year, the international community has faced many Protracted armed conflicts and energy crisis and disruptions to global trade have been compounded by destabilization orchestrated by those who pursue their own selfish ambitions. For small island economies, these are not distant events. Every rise in the price of fuel is felt in the cost of shipping. electricity, food, and essential services, placing a heavy burden on communities that have no buffer against external shocks."},{"t":275,"topic":"Pacific security","text":"These tensions confirm what Solomman Islands has long understood. Peace and security are inseparable from development. Neither can be secured without the other. There are no winners in war, only graves, orphans, and the long labor of rebuilding what conflict has torn down. There is no substitute for dialogue, diplomacy, and peaceful negotiation. Solomon Islands calls on all parties to armed conflicts to protect civilians and return to the negotiating table and act in full respect of international law. And it is why the world needs a stronger, more agile United Nations, one equipped to respond to the realities of Mr. President, the Pacific faces a grave and growing threat. Transnational criminal networks are using our ocean as a highway for illicit drugs, undermining our sovereignty and national security, destroying young lives and tearing at the fabric of our communities."},{"t":347,"topic":"Solomon Islands crime","text":"Behind every statistic stands a family, a community, a young life robbed of its We will not allow criminal networks to profit from the vulnerability of our We are amending our dangerous drugs act to in introduce stiffer penalties as a deterrent and we are strengthening law enforcement to prevent and detect these crimes and to hold perpetrators accountable. In August this year, Solomon Islands succeeded to the UN convention against transnational organized crime, a clear demonstration of our resolve to confront this threat. These are costly and demanding undertakings and no Pacific country can win this fight alone. We call for stronger international cooperation, greater information sharing, sustained investment in the capacity of our law enforcement agencies and the support uh for prevention uh and rehabilitation."},{"t":410,"topic":"Pacific security","text":"Our vision of a peaceful and secure Pacific extends beyond transnational crime. As enshrined in the Ocean of Peace Declaration, our region must remain free of nuclear weapons and free from destabilizing external influence. In keeping with that vision, my government has proposed a treaty that would bind Pacific Island countries and like-minded partners to a firm shared commitment to keep the Pacific an ocean of peace. Mr. President, artificial intelligence and emerging technologies present both unprecedented opportunities and serious risks. They can accelerate sustainable development, transform education and health care, strengthen disaster preparedness, and open new economic pathways for developing countries. But a widening digital divide threatens to leave developing countries further behind."},{"t":472,"topic":"Solomon Islands digital","text":"For my government, digital transformation is not about technology for its own sake. It is about connecting our scattered islands and opening the modern economy to every Solomon Islander. The completion of 161 telecommunication towers across the country will lift national broadband coverage from 56 to 86%. Expanding access to information, education, and digital financial The benefits of AI must be shared by all, Mr. president not concentrated among a few. Its risks, including its use for non- peaceful purposes, must be governed by all, not left to a few. Solomon Islands therefore recognizes the need for an inclusive and transparent international governance framework on Mr. President, year after year, Pacific leaders have stood at this podium and urged the world to act on climate change."},{"t":534,"topic":"Pacific climate","text":"And yet global action continues to fall short of what the science For every passing COP, the impacts grow more severe. Our islands are being lost to the sea. Disasters are more frequent and more Food and sec water security is under threat. And communities are being forced from their ancestral lands. Solomon Islands knows this reality This year, tropical cyclone miler, a category 5 storm, tore through our communities, destroying homes, schools, infrastructure, and livelihoods. My government has just approved US 9.38 million for shelter recovery. That is money our essential services urgently need now diverted to deal with the impacts of this climate extreme. Like many Pacific Island countries, we are trapped in a relentless cycle of response, recovery, and rebuilding."},{"t":601,"topic":"Pacific climate","text":"This is not sustainable, nor is it just. My people did the least to cause this crisis, yet they pay its earliest and heaviest price. That is the moral ledger that lies before this Last year, the International Court of Justice confirmed in its landmark advisory opinion that states have legal obligations to protect the climate Major emitters must make deep emission cuts and trans transition away from fossil fuels. Climate finance, including support for loss and damage, must be grant-based and channeled through our national budget Project-based financing of climate action is unsustainable and out of step with the scale of a crisis we did the least to cause. Vulnerable countries should not have to choose between climate action and educating our children, caring for the sick, or securing food and water."},{"t":666,"topic":"Pacific climate","text":"Yet, that is the choice we face with every dollar we spend. We therefore call for the full capitalization of the Pacific Resilience Facility and an ambitious and timely third replenishment of the Green Climate Fund. Our region has long led on climate action and we will continue to lead. The pre-COP 31 meeting to be hosted in the Pacific by Australia in partnership with Fiji and Tuvalu will bring the reality of climate change directly into the heart of the global process. I call on all parties and partners to come to that meeting and to COP 31 with stronger commitments and concrete action. The communities on the front line of the climate crisis deserve nothing less. Mr. President, Solomon Islands welcomes the convening of the second high level meeting on sea level rise and the adoption of the first political declaration on sea level rise."},{"t":729,"topic":"Pacific climate","text":"Every day our people are defending their coastlines, strengthening their resilience, protecting their food and water security and their cultural heritage. and where there is no other choice, relocating. But we cannot do this alone. I call on this assembly to match the courage of our Pacific communities with collective international resolve to scale up adaptation and res resilience finance and to support communities facing climate mobility needs. Solomon Islands reaffirm reaffirms that maritime boundaries once established and deposited in accordance with UNCLO together with the rights and entitlements that flow from them shall continue to apply notwithstanding any physical changes caused by climate change related sea level rise. Sir, the ocean is not simply a resource."},{"t":792,"topic":"Solomon Islands ocean","text":"It is our identity, our heritage, and our future. It sustains our livelihoods, our culture, and our economy. We do not own the ocean. We belong to it. We hold it in solemn trust for generations yet to be born. Yet our ability to benefit fully from our own ocean is undermined by illegal, unreported and unregulated fishing which costs our region US30 million every year. Solomon Islands is fighting back, working with the Foreign Fisheries Agency and partners including Australia, France, New Zealand, and the US to strengthen surveillance and enforcement across our waters. Mr. President, the SDG14 remains among the least funded of all the sustainable development goals. With just four years left until 2030, the fourth UN Ocean Conference must raise the bar on ocean finance and secure the oceanceans's place in the development agenda beyond Solomon Islands welcomes the entry into force of the BBNJ agreement and the preparations for the first conference of the parties in January."},{"t":874,"topic":"Ocean pollution","text":"We look to that conference to establish without delay the secretariat and the institutional arrangements to implement the agreement. Plastic pollution is poisoning our ocean and our food. As negotiations resume in Bangkok, Solomon Islands calls for an ambitious, legally binding treaty that addresses the full cycle of plastics from production to disposal. Mr. President, our people are our greatest asset. With more than half of our population under the age of 25, my government is prioritizing legal frameworks that empower young people, advance gender equality, and strengthen the protection of women and children against domestic violence. We welcome global progress in advancing the rights and full participation of women and persons with disabilities in the economy, and Solomon Islands is committed to accelerating that progress at home."},{"t":937,"topic":"Solomon Islands development","text":"There can be no sustainable development without equal opportunity for all. Mr. President, our development partnerships play an indispensable role in expanding infrastructure, maritime connectivity, health and education, and in improving the lives of Solomon Islanders. I thank the governments and peoples of Australia, China, Japan, New Zealand, the Republic of Korea and the US as well as the EU for their contributions to our national South South Corporation remains an important complement to ODA. Partnerships among developing countries have enabled us to share expertise, technology, innovation and practical solutions suited to our circumstances. The support of Papu Guinea, Indonesia, India and our Pacific family embodies the true spirit of South South solidarity and we value it deeply."},{"t":1000,"topic":"Solomon Islands climate","text":"We also acknowledge the partnership of multilateral organizations, NOS's and the private sector in supporting development work in Solomon Islands. At home, my government is working hand in hand with churches to build stronger, more inclusive Cooperation and partnership at every level and across borders are critical to nation building and my government remains fully committed to them. Mr. President, as a small island developing state, our vulnerability remains a fundamental reality. This a single natural disaster can erase years of investment and progress and push the nation backwards. The multi-dimensional vulnerability index captures the special circumstances of of SIDS in a way that income measures alone does not. We call on international financial institutions to in integrate the MVI into their financing decisions for SIDS without further delay."},{"t":1070,"topic":"Global military","text":"Mr. President, last year the world's the world spent more than $3 trillion on its That is more than 16 times all ODA. In less than 18 days, the world spends more on arms than developed countries provide in a full year of climate finance. In a in the same year that military spending reached its highest share of global output since 2009, development aid had its steepest fall on record. Bilateral aid to the least developed countries fell by a quarter. This imbalance must be corrected. Redirecting even a small share of this spending would fully capitalize the Pacific Resilience Facility and the loss and damage fund, secure the Green Climate Fund's third replenishment, and meet ODA targets. The resources exist. What is missing is the will, and the time to act is now."},{"t":1136,"topic":"Solomon Islands economy","text":"Sir, Solman Islands is due to graduate from least developed country status in As part of our preparations, my government is pursuing an ambitious and proactive agenda that uses public private partnerships to unlock investments in transformative projects, special economic zones and key sectors, a second tuna canary at Beina Harour, upgraded airports, agricultural treatment facilities to support trade, and expanded road networks and maritime ports will shift the trajectory. of our At the same time, my government is strengthening our financial institutions and frameworks to improve revenue collection and accountability so that we can sustain our development priorities. These reforms reflect our commitment to a strong and resilient economy that delivers decentralized people centered development across the country. Our ambition is clear to graduate from LDC status with confidence to strengthen the foundations of our economy and to ensure that development delivers lasting opportunities for every Solomon Mr."},{"t":1217,"topic":"UN reform","text":"President, as the UN marks it its 81st anniversary, it must continue to evolve to meet today's challenges while remaining faithful to its founding The UN80 reform process must strengthen the organization's effectiveness and relevance without diminishing its presence, services or support in the most vulnerable regions where assistance is needed most. Reform must enhance delivery, not reduce it. The UN is not perfect, but it remains the cornerstone of multilateral diplomacy and the indispensable platform through which nations preserve peace, advance sustainable development, uphold international law, and protect human Solomon Islands looks to the next secretary general to lead with vision and to ensure that the secretariat is accountable to all member states serving the interests of small and large states on an equal footing."},{"t":1287,"topic":"UN reform","text":"Mr. President Solomon Islands reiterates its support for comprehensive reform of the Security Council to make it more representative, transparent, accountable, and reflective of today's A council with a dedicated seat for small island developing states would strengthen the legitimacy and effectiveness of the entire multilateral The veto is a relic of 1945. Too often, it has been used to shield violations of international law and to entrench the double standards that fuel conflict. At a minimum, the veto must never again be used in situations of genocide, crimes against humanity, or war crimes. Ultimately, it should be Mr. President, it is with great pride that Solomon Islands is again contributing personnel to UN peacekeeping in South Sudan. Despite our small size, our participation reaffirms our enduring commitment to the charter, to international peace and security, and to the noble work of peacekeepers serving communities affected by conflict."},{"t":1362,"topic":"West Papua","text":"I thank our partners including Australia and the UN police for their support. Solman Islands looks forward to increasing its peacekeeping contribution in the coming year. Mr. President, leaving no one behind demands that we complete the unfinished work of decolonization. Solomon Islands reaffirms its long-standing support for the right to self-determination of the Kanak people of New Calonia and the Maui Nui people of French Polynesia. The UN decolonization process must offer more than hope. It must provide practical pathways to the full emancipation of peoples in non-self-governing territories and to their freedom to determine their own political future and development In the same spirit, I turn to West Papua, whose people are our Melnishian brothers and sisters. Solomon Islands respects the sovereignty and territorial integrity of the Republic of Indonesia and we value our friendship with its government and Yet, it is precisely because of that friendship that we speak with Kanda."},{"t":1438,"topic":"West Papua","text":"Reports of human rights violations in West Papua have persisted for far too long. They must be independently verified, not left in dispute. We therefore renew the call of Pacific Islands forum leaders for the government of Indonesia to facilitate without further delay the long- awaited visit of the UN High Commissioner for Human Rights to West Papua. Such a visit is an act of confidence between friends and an affirmation that there is nothing to hide and there is nothing to fear from the light. Mr. President, in closing, the challenges of our time demand renewed stronger multilateralism, and genuine commitment to the principles of the UN charter. But institutions do not have hearts. People do. Charters do not keep the peace. The men and women who honor them do."},{"t":1502,"topic":"Solomon Islands governance","text":"Beyond every declaration and commitment, each of us carries a profound responsibility to be agents of peace, champions of goodwill, and keepers of the fragile bonds of friendship among nations. The world has never needed that spirit more than it does today. Mr. President, permit me a word from the Christian faith that has shaped my people. Our constitution was established under the guiding hand of God by a people conscious of our common destiny. We believe that is true not only of Solomon Islands but of this whole family of nations. We live in a time when division has become the calling card of the day. Nations are sorted into camps. Neighbors are asked to choose sides. Small states are too often treated as prizes to be won rather than partners to be heard. But the destiny of nations does not finally rest in this general assembly, nor in any capital, however powerful."},{"t":1570,"topic":"Solomon Islands governance","text":"King Solomon, among the wisest rulers of antiquity, wrote, \"There are many devices in a man's heart. Nevertheless, the council of the Lord shall stand.\" that truth does not make us passive. It makes us humble and it makes us accountable. So I call on my fellow fellow leaders to do three things. First, let us ask for wisdom before we ask for advantage. When Solomon was offered anything he he did not ask for riches or long life or the defeat of his enemies. He asked for an understanding heart so that he might judge his people well. I can think of no better prayer for every leader in this room. Second, let us stay at the table. The same king taught that in the multitude of counselors there is safety. That is the oldest case I know for what this organization is meant to be."},{"t":1632,"topic":"Solomon Islands justice","text":"Many nations large and small sitting together because none of us sees far enough Third, let us measure greatness rightly. Righteousness exalts the nation. Not its arsenal, not its alliances, but its justice. How it treats the poor, the displaced, and the small. Powers rise and powers fall. The purposes of God endure. Let us choose cooperation over division, dialogue over peace over hostility, and action over inaction. And let us lead as people who know we will answer for it one day. Our national moto teaches us that to lead is to serve. In that spirit of service, Solomman Island stands ready to do its part as a willing partner and a committed member of this assembly. May God bless our shared family of nations."},{"t":1697,"topic":null,"text":"Thank you. On behalf of the assembly, I wish to thank the prime minister of Solomon"}],"compare":[{"topic":"Climate Change","share":0.1527,"mean":0.0422,"rank":14,"others":77},{"topic":"UN & its reform","share":0.1297,"mean":0.2052,"rank":130,"others":170},{"topic":"Indonesia","share":0.0826,"mean":0.0002,"rank":1,"others":1},{"topic":"Indo-Pacific","share":0.0788,"mean":0.0037,"rank":4,"others":6},{"topic":"Regional Security","share":0.0388,"mean":0.0044,"rank":12,"others":12},{"topic":"Ocean Governance","share":0.0367,"mean":0.0066,"rank":16,"others":16}]};
